{
  "findings": [
    {
      "ref": "[D537]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with the child, and this feature is on by default.",
      "stance": "risk",
      "quote": "The default setting is \"Block\" meaning chat/message is restricted."
    },
    {
      "ref": "[D537]",
      "area": "contact",
      "claim": "A parent reports that the child can still send and receive predetermined text messages created by a game or app, and can use communication services via the Internet Browser unless specifically disabled.",
      "stance": "risk",
      "quote": "when this control is set to block, a Sub Account can still A) send and receive predetermined text messages created by a game or app, B) create and see other users' in-game character names, designs, and clan titles, C) use communication services via the Internet Browser unless specifically disabled and D) communicate via system messaging on PS3 and PS Vita systems, E) communicate via third party, non-game apps."
    },
    {
      "ref": "[D537]",
      "area": "money",
      "claim": "A parent reports that the app allows in‑app purchases and the default monthly spending limit is $0.00, meaning purchases are blocked unless a limit is set.",
      "stance": "mitigation",
      "quote": "The default value is set to \"$0.00\" meaning the Sub Account cannot make any purchases."
    },
    {
      "ref": "[D537]",
      "area": "data",
      "claim": "A parent reports that the app may collect user‑generated media and other content, but the text does not specify data collection or sharing practices.",
      "stance": "neutral",
      "quote": "This control will not prevent video capture of the sub account user's online gameplay."
    },
    {
      "ref": "[D537]",
      "area": "age_gating",
      "claim": "A parent reports that the app includes an age gate that blocks chat and user‑generated media by default, but the effectiveness depends on parental settings.",
      "stance": "mitigation",
      "quote": "The default setting is \"Block\" meaning chat/message is restricted."
    },
    {
      "ref": "[D537]",
      "area": "content",
      "claim": "A parent reports that the app can block user‑generated media (photos, videos, drawings) from being posted or viewed.",
      "stance": "mitigation",
      "quote": "This parental control blocks a Sub Account from posting or viewing user-generated content (including photos, videos, drawings, and content imported from outside sources)."
    },
    {
      "ref": "[D537]",
      "area": "developer_record",
      "claim": "A parent reports no known fines, breaches, lawsuits or regulatory actions against the developer are mentioned in the text.",
      "stance": "neutral",
      "quote": "No information is provided about fines, breaches, lawsuits or regulatory actions."
    }
  ]
